// Blink the on-board LED, print state, and let a button (pin 2 -> GND) pause it.
const int LED = LED_BUILTIN;
const int BTN = 2;
unsigned long last = 0;
const unsigned long PERIOD = 500;
bool on = false;

void setup() {
  pinMode(LED, OUTPUT);
  pinMode(BTN, INPUT_PULLUP);
  Serial.begin(115200);
  Serial.println("Grg Code blink starting");
}

void loop() {
  bool paused = digitalRead(BTN) == LOW;   // button held = pause
  if (!paused && millis() - last >= PERIOD) {
    last = millis();
    on = !on;
    digitalWrite(LED, on ? HIGH : LOW);
    Serial.println(on ? "LED on" : "LED off");
  }
}
